    public void draw_automation_lane(Control o,Settings track,double y)
    {
        using var lanes=new AudioAutomationLaneOperations();var info=lanes.lane_info(Document(o),S(track,"id"));var font=o.Get("_font").As<Font>();if(info.Count==0){o.DrawString(font,new Vector2(LabelWidth+12,(float)y+35),"Target missing or unassigned. Choose T to link a parameter.",HorizontalAlignment.Left,Math.Max(1,o.Size.X-LabelWidth-20),11,new Color("d9ba78"));return;}var points=lanes.points(info);double left=Math.Max(LabelWidth,x_at(o,N(info,"offset"))),right=o.Size.X;if(S(info["target"].AsGodotDictionary(),"owner_kind")=="clip")right=Math.Min(right,x_at(o,N(info,"offset")+N(info,"duration")));if(right<=left)return;var color=new Color(lanes.editable(Document(o),S(track,"id"))?"edc874":"82919c");int samples=Math.Max(1,(int)Math.Ceiling((right-left)/6));var previous=Vector2.Zero;for(int i=0;i<=samples;i++){double x=Mathf.Lerp(left,right,(double)i/samples),local=Math.Max(0,time_at(o,x)-N(info,"offset")),value=lanes.value(points,local,N(info,"fallback"));var at=automation_point_position(o,info,new Settings{["time"]=local,["value"]=value},y);if(i>0)o.DrawLine(previous,at,color,1.5f);previous=at;}foreach(var raw in points){var at=automation_point_position(o,info,raw.AsGodotDictionary(),y);if(at.X>=left&&at.X<=right)o.DrawCircle(at,4,color);}if(points.Count==0)o.DrawString(font,new Vector2((float)left+6,(float)y+18),"Ctrl-click to add · double-click to edit",HorizontalAlignment.Left,(float)Math.Max(1,right-left-12),10,new Color("819aab"));
    }
