        o.DrawRect(new Rect2(Vector2.Zero,o.Size),new Color("101820"));var session=Session(o);if(session==null)return;var document=Document(o);var conductor=project_conductor(o);using var conductorOps=new AudioConductorOperations();using var lanes=new AudioAutomationLaneOperations();using var sources=new AudioSourceCacheOperations();var font=o.Get("_font").As<Font>();double zoom=N(o,"zoom"),height=N(o,"track_height"),scroll=N(o,"track_scroll"),previousLabel=-1000;foreach(var point in conductorOps.grid(conductor,N(o,"scroll_time"),N(o,"scroll_time")+Math.Max(0,o.Size.X-LabelWidth)/zoom,zoom)){float x=(float)x_at(o,N(point,"seconds"));if(x<LabelWidth)continue;bool major=Get(point,"downbeat",false).AsBool();o.DrawLine(new Vector2(x,Ruler),new Vector2(x,o.Size.Y),new Color(major?"354753":"202d37"));if(x-previousLabel>=48&&(major||zoom*60/conductorOps.tempo_at(conductor,N(point,"seconds"))*N(point,"unit")>55)){o.DrawString(font,new Vector2(x+4,19),(int)N(point,"bar")+"."+(int)N(point,"beat"),HorizontalAlignment.Left,-1,11,new Color("9eb6c6"));previousLabel=x;}}
