.Y),rect.Position+new Vector2(fadeIn,0),fadeColor,1.5f);o.DrawLine(new Vector2(rect.End.X-fadeOut,rect.Position.Y),rect.End,fadeColor,1.5f);o.DrawCircle(rect.Position+new Vector2(fadeIn,3),4,fadeColor);o.DrawCircle(new Vector2(rect.End.X-fadeOut,rect.Position.Y+3),4,fadeColor);}
        }
