        o.DrawRect(new Rect2(0,0,LabelWidth,o.Size.Y),new Color("17232e"));o.DrawString(font,new Vector2(12,20),"TRACKS  /  BARS · BEATS",HorizontalAlignment.Left,155,10,new Color("89a8ba"));for(int index=0;index<tracks.Count;index++){var track=tracks[index].AsGodotDictionary();float y=(float)(Ruler+index*height-scroll);if(y+height<Ruler||y>o.Size.Y)continue;if(S(track,"id")==Text(session,"selected_track"))o.DrawRect(new Rect2(0,y,LabelWidth,(float)height),new Color("223b45"));o.DrawRect(new Rect2(0,y,4,(float)height),Get(track,"color",new Color("63d9bc")).AsColor());o.DrawString(font,new Vector2(12,y+22),S(track,"name"),HorizontalAlignment.Left,LabelWidth-25,13,new Color("e3edf2"));bool lane=lanes.is_lane(track);double db=N(track,"volume_db");string sublabel=lane?S(lanes.lane_info(document,S(track,"id")),"label","CHOOSE A TARGET"):S(track,"kind").ToUpperInvariant()+"  "+(db>=0?"+":"")+db.ToString("F1",CultureInfo.InvariantCulture)+" dB";o.DrawString(font,new Vector2(12,y+40),sublabel,HorizontalAlignment.Left,160,10,new Color("8aa3b5"));for(int b=0;b<3;b++){bool active=lane&&b==2?Get(track,"locked",false).AsBool():!lane&&Get(track,new[]{"mute","solo","locked"}[b],false).AsBool();Box(o,new Color(active?"4a7668":"273744"),new Color("496574"),new Rect2(12+b*40,y+49,32,22));o.DrawString(font,new Vector2(15+b*40,y+64),(lane?new[]{"Edit","Target","Lock"}:new[]{"Mute","Solo","Lock"})[b],HorizontalAlignment.Center,26,9,new Color("d7e8ec"));}}
    }
